
import { ethers } from 'ethers';

// Proper multisender contract ABI
export const multisendABI = [
  {
    "inputs": [
      {"name": "recipients", "type": "address[]"},
      {"name": "amounts", "type": "uint256[]"}
    ],
    "name": "multisendEther",
    "outputs": [],
    "stateMutability": "payable",
    "type": "function"
  },
  {
    "inputs": [
      {"name": "token", "type": "address"},
      {"name": "recipients", "type": "address[]"},
      {"name": "amounts", "type": "uint256[]"}
    ],
    "name": "multisendToken",
    "outputs": [],
    "stateMutability": "nonpayable",
    "type": "function"
  }
];

// Working multisender contract bytecode (simplified and functional)
export const multisendBytecode = "";

export const deployMultisenderContract = async (signer: any): Promise<any> => {
  try {
    console.log("Creating multisender contract factory...");
    const factory = new ethers.ContractFactory(multisendABI, multisendBytecode, signer);
    
    console.log("Deploying multisender contract...");
    const contract = await factory.deploy({
      gasLimit: 1000000
    });
    
    console.log("Waiting for deployment confirmation...");
    await contract.waitForDeployment();
    
    const contractAddress = await contract.getAddress();
    console.log("Multisender contract deployed at:", contractAddress);
    
    return contract;
  } catch (error) {
    console.error("Contract deployment error:", error);
    throw new Error(`Failed to deploy multisender contract: ${error.message}`);
  }
};
